import {
    Table,
    IntegerColumn,
    ReferenceColumn,
    StringColumn,
    DateTimeColumn,
    DomainIdColumn,
    DomainPathColumn,
} from '../../db'

export const sys_ui_form_section = Table({
    name: 'sys_ui_form_section',
    schema: {
        position: IntegerColumn({ mandatory: false, label: 'Position', read_only: false, active: true, maxLength: 40 }),
        sys_overrides: ReferenceColumn({
            mandatory: false,
            label: 'Overrides',
            read_only: false,
            active: true,
            maxLength: 32,
            referenceTable: 'sys_ui_form_section',
        }),
        sys_ui_form: ReferenceColumn({
            mandatory: false,
            label: 'Sys UI form',
            read_only: false,
            active: true,
            maxLength: 32,
            referenceTable: 'sys_ui_form',
        }),
        sys_ui_section: ReferenceColumn({
            mandatory: false,
            label: 'Sys UI section',
            read_only: false,
            active: true,
            maxLength: 32,
            referenceTable: 'sys_ui_section',
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                },
            ],
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                },
            ],
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the form section belongs',
                    label: 'Domain',
                    plural: 'Domains',
                },
            ],
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                },
            ],
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                },
            ],
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                },
            ],
        }),
    },
})
